WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),micro AS (SELECT DISTINCT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,p.id_car_norm,p.cpf,p.cnpj_basico,c.id_imovel,c.id_municipio FROM p JOIN car c USING(id_car_norm) WHERE c.area<0.1),doc AS (SELECT id_municipio,COALESCE(NULLIF(cpf,''),NULLIF(cnpj_basico,'')) documento,id_car_norm,ano_emissao FROM micro WHERE COALESCE(NULLIF(cpf,''),NULLIF(cnpj_basico,'')) IS NOT NULL),x AS (SELECT id_municipio,documento,COUNT(DISTINCT id_car_norm) imoveis_por_mutuario,COUNT(DISTINCT ano_emissao) anos_por_mutuario FROM doc GROUP BY 1,2),summary AS (SELECT id_municipio,COUNT(DISTINCT documento) mutuarios,COUNT(DISTINCT id_car_norm) imoveis_micro,COUNTIF(imoveis_por_mutuario>1) mutuarios_com_varios_imoveis,MAX(imoveis_por_mutuario) max_imoveis_por_mutuario FROM x GROUP BY 1),cars AS (SELECT id_municipio,id_car_norm,COUNT(DISTINCT COALESCE(NULLIF(cpf,''),NULLIF(cnpj_basico,''))) mutuarios_por_imovel FROM doc GROUP BY 1,2) SELECT s.*,COUNTIF(c.mutuarios_por_imovel>1) imoveis_com_varios_mutuarios,MAX(c.mutuarios_por_imovel) max_mutuarios_por_imovel FROM summary s JOIN cars c USING(id_municipio) GROUP BY s.id_municipio,s.mutuarios,s.imoveis_micro,s.mutuarios_com_varios_imoveis,s.max_imoveis_por_mutuario ORDER BY s.id_municipio